def transpose(matrix):
    """Transpose a rectangular matrix (list of equal-length row lists)."""
    if not matrix:
        return []
    rows = len(matrix)
    cols = len(matrix[0])
    result = []
    for c in range(cols):
        row = []
        for r in range(rows):
            row.append(matrix[r][c])
        result.append(row)
    return result


def column_sums(matrix):
    """Sum of each column, left to right."""
    if not matrix:
        return []
    cols = len(matrix[0])
    sums = [0] * cols
    for row in matrix:
        for c in range(cols):
            sums[c] += row[c]
    return sums


def row_maxes(matrix):
    """Maximum value of each row, top to bottom."""
    maxes = []
    for row in matrix:
        best = row[0]
        for v in row:
            if v > best:
                best = v
        maxes.append(best)
    return maxes

