from matrixops import column_sums, row_maxes, transpose


def test_transpose_rectangular():
    assert transpose([[1, 2, 3], [4, 5, 6]]) == [[1, 4], [2, 5], [3, 6]]


def test_transpose_empty():
    assert transpose([]) == []


def test_transpose_single_row():
    assert transpose([[1, 2, 3]]) == [[1], [2], [3]]


def test_column_sums():
    assert column_sums([[1, 2, 3], [4, 5, 6]]) == [5, 7, 9]


def test_row_maxes_non_square():
    # 2 rows x 3 cols: row-wise (not column-wise) maxima
    assert row_maxes([[1, 9, 2], [7, 3, 4]]) == [9, 7]


def test_row_maxes_single_row():
    assert row_maxes([[5, 1, 5]]) == [5]

